// Programmatic registry for the routes with a published fixed price (Helicro price list, September 2026).
// One entry per route and language; content is generated by src/lib/seoContent/pricedRoute.ts.
import { DESTINATIONS, PRICED_ROUTES, SHARED_SHUTTLE, type PricedRoute } from './seoFacts';
import type { SEOPage } from './seoPages';

export type PricedLang = 'en' | 'nl' | 'fr';

