  'brussels-lille-airport': { en: '/en/airport-transfer/lille', nl: '/nl/route/brussel-rijsel-luchthaven', fr: '/fr/navette/bruxelles-lille-aeroport' },
  'brussels-paris-cdg': { en: '/en/route/brussels-paris-cdg', nl: '/nl/route/brussel-parijs-cdg', fr: '/fr/navette/bruxelles-paris-cdg' },
