  'brussels-eindhoven': { en: '/en/route/brussels-eindhoven', nl: '/nl/route/brussel-eindhoven', fr: '/fr/navette/bruxelles-eindhoven' },
  'brussels-amsterdam': { en: '/en/route/brussels-amsterdam', nl: '/nl/route/brussel-amsterdam', fr: '/fr/navette/bruxelles-amsterdam' },
  'brussels-maastricht': { en: '/en/route/brussels-maastricht', nl: '/nl/route/brussel-maastricht', fr: '/fr/navette/bruxelles-maastricht' },
  'brussels-dusseldorf': { en: '/en/route/brussels-dusseldorf', nl: '/nl/route/brussel-dusseldorf', fr: '/fr/navette/bruxelles-dusseldorf' },
  'brussels-cologne': { en: '/en/route/brussels-cologne', nl: '/nl/route/brussel-keulen', fr: '/fr/navette/bruxelles-cologne' },
  'brussels-frankfurt': { en: '/en/route/brussels-frankfurt', nl: '/nl/route/brussel-frankfurt', fr: '/fr/navette/bruxelles-francfort' },
