/** All generated SEOPage entries (routes with a fixed price plus the shared shuttle), all languages. */
export const pricedRoutePages: SEOPage[] = [
  ...PRICED_ROUTES.flatMap((route) => {
    const urls = PRICED_ROUTE_URLS[route.key];
    if (!urls) return [];
    return (Object.keys(urls) as PricedLang[])
      .filter((lang) => !EXTERNAL_PAGES.has(urls[lang]!))
      .map((lang) => buildPage(route, lang, urls[lang]!));
  }),
  SHARED_PAGES.en,
  SHARED_PAGES.nl,
  SHARED_PAGES.fr,
];

/** Resolve a URL to the priced route it represents. */
export function pricedRouteFor(url: string): { route: PricedRoute; lang: PricedLang } | null {
  for (const route of PRICED_ROUTES) {
    const urls = PRICED_ROUTE_URLS[route.key];
    if (!urls) continue;
    for (const lang of Object.keys(urls) as PricedLang[]) {
      if (urls[lang] === url && !EXTERNAL_PAGES.has(url)) return { route, lang };
    }
  }
  return null;
}

export function sharedShuttleLangFor(url: string): PricedLang | null {
  const hit = (Object.keys(SHARED_SHUTTLE_URLS) as PricedLang[]).find((l) => SHARED_SHUTTLE_URLS[l] === url);
  return hit ?? null;
}
